const $=s=>document.querySelector(s);
$('#year').textContent=new Date().getFullYear();
const menu=$('.menu'),nav=$('#navigation');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});
const reduced=matchMedia('(prefers-reduced-motion: reduce)'),saveData=navigator.connection?.saveData;
let paused=!!(reduced.matches||saveData),active=0;
const toggle=$('#motion-toggle'),dialog=$('#video-dialog'),player=dialog.querySelector('video'),track=$('#highlight-track');
const media=window.WEBAR_MEDIA||{projects:[]};
const fluxVideo=$('#flux-preview');
if(fluxVideo&&media.shortForm){fluxVideo.dataset.src=media.shortForm.preview;fluxVideo.poster=media.shortForm.poster;$('#flux-watch').addEventListener('click',()=>openVideo(media.shortForm));}
if(media.headshot?.src){const img=document.createElement('img');img.src=media.headshot.src;img.alt=media.headshot.alt||'Emmanuel Agbo';img.width=160;img.height=190;$('#headshot-slot').replaceChildren(img);$('#headshot-slot').classList.add('has-headshot');}
const supplied=(media.highlights||[]).filter(p=>p.preview||p.full);if(!supplied.length&&media.hero?.preview)supplied.push(media.hero);
const highlights=supplied.length?supplied:[
{title:'The art of the edit',line:'Every frame.',accent:'A feeling.',label:'MOTION STUDY / DESIGN PREVIEW',style:'edit'},
{title:'Podcast trailers',line:'The moment.',accent:'The hook.',label:'PODCAST TRAILERS / HIGHLIGHTS COMING SOON',style:'trailer'},
{title:'Shorts & reels',line:'Stop scrolling.',accent:'Start watching.',label:'SHORTS & REELS / HIGHLIGHTS COMING SOON',style:'shorts'}];
const slides=[],dots=[];let returnFocus;
function openVideo(project){returnFocus=document.activeElement;document.querySelectorAll('video').forEach(v=>v.pause());$('#video-title').textContent=project.title;$('#video-description').textContent=[project.client,project.role,project.description].filter(Boolean).join(' · ');player.src=project.full||project.preview;dialog.showModal();document.body.style.overflow='hidden';syncMotion();player.play().catch(()=>{});}
$('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close()}});dialog.addEventListener('close',()=>{player.pause();player.removeAttribute('src');player.load();document.body.style.overflow='';syncMotion();returnFocus?.focus();});
function syncMotion(){const stop=paused||document.hidden||dialog.open;toggle.setAttribute('aria-label',paused?'Play motion previews':'Pause motion previews');toggle.innerHTML=paused?'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m8 5 11 7-11 7z"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 5v14M15 5v14"/></svg>';slides.forEach((slide,i)=>{const running=!stop&&i===active&&slide.dataset.visible==='true';slide.classList.toggle('paused',!running);const v=slide.querySelector('video');if(v){if(running){if(!v.src)v.src=v.dataset.src;v.play().catch(()=>{slide.classList.add('autoplay-blocked')});}else v.pause();}});if(fluxVideo){if(!stop&&fluxVideo.dataset.visible==='true'){if(!fluxVideo.src)fluxVideo.src=fluxVideo.dataset.src;fluxVideo.play().catch(()=>{});}else fluxVideo.pause();}}
const slideObserver=new IntersectionObserver(entries=>{for(const e of entries)e.target.dataset.visible=e.isIntersecting?'true':'false';syncMotion();},{threshold:.4});
highlights.forEach((p,i)=>{const slide=document.createElement('div');slide.className='showcase highlight-slide paused';slide.setAttribute('role','group');slide.setAttribute('aria-roledescription','slide');slide.setAttribute('aria-label',`${i+1} of ${highlights.length}: ${p.title}`);
const top=document.createElement('div');top.className='timecode';top.setAttribute('aria-hidden','true');const brand=document.createElement('span');brand.textContent='WEBAR / '+String(i+1).padStart(2,'0');const title=document.createElement('span');title.textContent=p.title.toUpperCase();top.append(brand,title);slide.append(top);
if(p.preview||p.full){const v=document.createElement('video');v.dataset.src=p.preview||p.full;v.muted=true;v.loop=true;v.playsInline=true;v.preload='none';if(p.poster)v.poster=p.poster;slide.append(v);const button=document.createElement('button');button.className='watch-highlight';button.textContent='Watch highlight with sound';button.addEventListener('click',()=>openVideo(p));slide.append(button);}else{const demo=document.createElement('div');demo.className='motion-demo motion-'+p.style;demo.innerHTML='<div class="orbit" aria-hidden="true"></div><div class="demo-label"></div><div class="motion-words"><span></span><strong></strong></div><div class="wave" aria-hidden="true"></div><div class="demo-caption">WEBAR MEDIA <span>STORY · RHYTHM · IMPACT</span></div>';demo.querySelector('.demo-label').textContent=p.title.toUpperCase();demo.querySelector('.motion-words span').textContent=p.line;demo.querySelector('.motion-words strong').textContent=p.accent;slide.append(demo);}
const caption=document.createElement('div');caption.className='showcase-controls';caption.textContent=p.label||p.title;slide.append(caption);track.append(slide);slides.push(slide);slideObserver.observe(slide);
const dot=document.createElement('button');dot.type='button';dot.setAttribute('aria-label',`Go to highlight ${i+1}: ${p.title}`);dot.addEventListener('click',()=>goTo(i));$('#highlight-dots').append(dot);dots.push(dot);});
function updatePosition(){const width=track.clientWidth;if(!width)return;active=Math.min(slides.length-1,Math.max(0,Math.round(track.scrollLeft/width)));$('#highlight-count').textContent=String(active+1).padStart(2,'0')+' / '+String(slides.length).padStart(2,'0');dots.forEach((dot,i)=>{dot.setAttribute('aria-pressed',i===active?'true':'false')});$('#highlight-prev').disabled=active===0;$('#highlight-next').disabled=active===slides.length-1;syncMotion();}
function goTo(index){index=Math.max(0,Math.min(slides.length-1,index));track.scrollTo({left:index*track.clientWidth,behavior:reduced.matches?'instant':'smooth'});}
track.addEventListener('scroll',updatePosition,{passive:true});track.addEventListener('keydown',e=>{if(e.target!==track)return;if(e.key==='ArrowRight'){e.preventDefault();goTo(active+1)}if(e.key==='ArrowLeft'){e.preventDefault();goTo(active-1)}if(e.key==='Home'){e.preventDefault();goTo(0)}if(e.key==='End'){e.preventDefault();goTo(slides.length-1)}});
$('#highlight-prev').addEventListener('click',()=>goTo(active-1));$('#highlight-next').addEventListener('click',()=>goTo(active+1));toggle.addEventListener('click',()=>{paused=!paused;syncMotion()});new ResizeObserver(()=>{track.scrollTo({left:active*track.clientWidth,behavior:'instant'});updatePosition();}).observe(track);updatePosition();
const fluxObserver=new IntersectionObserver(entries=>{entries.forEach(e=>e.target.dataset.visible=e.isIntersecting?'true':'false');syncMotion();},{threshold:.4});if(fluxVideo)fluxObserver.observe(fluxVideo);
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting)e.target.pause()}),{threshold:.35});document.addEventListener('visibilitychange',()=>{if(document.hidden)document.querySelectorAll('video').forEach(v=>v.pause());syncMotion()});
const projects=(media.projects||[]).filter(p=>p.title&&p.poster&&(p.full||p.preview));if(projects.length){$('#projects').hidden=false;const cats=['All',...new Set(projects.map(p=>p.category).filter(Boolean))];function render(cat){$('.project-grid').replaceChildren();for(const p of projects.filter(p=>cat==='All'||p.category===cat)){const card=document.createElement('button');card.className='project';card.type='button';const img=document.createElement('img');img.src=p.poster;img.alt=p.title;img.loading='lazy';card.append(img);if(p.preview){const v=document.createElement('video');v.dataset.src=p.preview;v.muted=true;v.loop=true;v.playsInline=true;v.preload='none';v.hidden=true;card.append(v);observer.observe(v);card.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'&&!reduced.matches&&!saveData){img.hidden=true;v.hidden=false;if(!v.src)v.src=v.dataset.src;v.play().catch(()=>{img.hidden=false;v.hidden=true})}});card.addEventListener('pointerleave',()=>{v.pause();v.hidden=true;img.hidden=false})}const title=document.createElement('h3');title.textContent=p.title+' ↗';const caption=document.createElement('p');caption.textContent=[p.client,p.category].filter(Boolean).join(' / ');card.append(title,caption);card.addEventListener('click',()=>openVideo(p));$('.project-grid').append(card)}}cats.forEach((cat,i)=>{const b=document.createElement('button');b.textContent=cat;b.setAttribute('aria-pressed',i===0?'true':'false');b.addEventListener('click',()=>{$('.filters').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed','false'));b.setAttribute('aria-pressed','true');render(cat)});$('.filters').append(b)});render('All')}
$('#enquiry').addEventListener('submit',e=>{e.preventDefault();if(!e.currentTarget.reportValidity())return;const f=new FormData(e.currentTarget);const brief=`Hello Emmanuel, I’d like to discuss a project.\n\nName: ${f.get('name')}\nEmail: ${f.get('email')}\nChannel: ${f.get('channel')||'Not provided'}\nServices: ${f.getAll('service').join(', ')||'To discuss'}\n\nProject: ${f.get('details')}\nTimeline: ${f.get('timeline')||'To discuss'}`;const url='https://wa.me/2348123051817?text='+encodeURIComponent(brief);const win=window.open(url,'_blank','noopener,noreferrer');$('#form-status').replaceChildren();const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Open your prepared brief in WhatsApp ↗';a.className='text-link';$('#form-status').append(a);});
